package org.springframework.amqp.rabbit.connection; import java.util.concurrent.*; public class CorrelationData { private final String id; private final CompletableFuture<Confirm> f=new CompletableFuture<>(); private Returned returned; public CorrelationData(String id){this.id=id;} public CompletableFuture<Confirm> getFuture(){return f;} public Returned getReturned(){return returned;} public record Confirm(boolean ack,String reason){public boolean isAck(){return ack;} public String getReason(){return reason;}} public static class Returned { public String getReplyText(){return "returned";} } }
